def differentiate(polynomial, x):
    terms = polynomial.split('+')
    derivative = 0
    for term in terms:
        if 'x' not in term:
            continue
        if '^' in term:
            coeff, exp = term.split('x^')
            coeff = int(coeff) if coeff and coeff != '-' else -1 if coeff == '-' else 1
            exp = int(exp)
            derivative += coeff * exp * (x ** (exp - 1))
        else:
            coeff = term[:-1]
            coeff = int(coeff) if coeff and coeff != '-' else -1
            derivative += coeff
    return derivative
